    /** A part's movements, newest logged first. With a limit, only that many of the latest logged. */
    history(partNo: string, limit?: number): Movement[] {
        if (limit !== undefined && !wholeAndAtLeast(limit, 1)) {
            throw new RangeError(`bad limit: ${limit}`);
        }
        const key = keyOf(partNo);
        const all = this.moves.filter((m) => m.partNo === key);
        const kept = limit === undefined ? all : all.slice(0, limit);
        return kept.map((m) => ({ ...m }));
    }
